#!/usr/bin/env bash
#
# Walks you through Neon + SMTP + Render + Vercel for the GameScore beta.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env.beta.local}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

banner "GameScore beta deploy (Neon + SMTP + Render + Vercel)"

# ── 1. JWT secrets (already generated into .env.beta.local if present) ────
stage "JWT secrets"
say "Production rejects secrets that contain 'dev-only-' or 'change-me'."
note "File: $ENV_FILE"
if JWT_EXISTING=$(_existing JWT_SECRET || true); [[ -n "${JWT_EXISTING:-}" && ${#JWT_EXISTING} -ge 32 ]]; then
  note "JWT_SECRET already set (${#JWT_EXISTING} chars). Keeping it."
else
  if command -v openssl >/dev/null 2>&1; then
    JWT_SECRET=$(openssl rand -base64 48)
    JWT_REFRESH_SECRET=$(openssl rand -base64 48)
  else
    JWT_SECRET=$(node -e "console.log(require('crypto').randomBytes(48).toString('base64'))")
    JWT_REFRESH_SECRET=$(node -e "console.log(require('crypto').randomBytes(48).toString('base64'))")
  fi
  write_env JWT_SECRET "$JWT_SECRET"
  write_env JWT_REFRESH_SECRET "$JWT_REFRESH_SECRET"
fi
write_env NODE_ENV production
write_env LOG_LEVEL info
write_env ENABLE_SWAGGER false
write_env JWT_ACCESS_TOKEN_TTL 900
write_env JWT_REFRESH_TOKEN_TTL 2592000
pause "JWTs ready. Press Enter."

# ── 2. Neon Postgres ──────────────────────────────────────────────────────
stage "Neon Postgres"
say "Create a free Neon project and copy the connection string."
open_url "https://console.neon.tech/app/projects"
step "Sign in → New Project → name it gamescore-beta."
step "Open Connection Details → copy the connection string (prefer pooled)."
step "It must include sslmode=require (Neon usually adds this)."
ask_secret DATABASE_URL "Paste DATABASE_URL:"
write_env DATABASE_URL "$DATABASE_URL"
say "Apply migrations from this machine (needs pnpm + network):"
note "  DATABASE_URL='…' pnpm db:migrate:deploy"
if confirm "Run migrations now from this repo?"; then
  DATABASE_URL="$DATABASE_URL" corepack pnpm db:migrate:deploy || warn "migrate failed — run pnpm db:migrate:deploy later"
fi
warn "Never run pnpm db:seed against Neon."
pause "Neon done. Press Enter."

# ── 3. SMTP (Resend recommended) ──────────────────────────────────────────
stage "SMTP (Resend)"
say "Production API requires SMTP_HOST + SMTP_FROM for verification emails."
open_url "https://resend.com/signup"
step "Create a free Resend account."
step "Domains → add a domain, OR use the onboarding test sender if Resend still offers it."
step "API Keys → Create → copy the key (re_…)."
ask SMTP_FROM "SMTP_FROM (e.g. GameScore <onboarding@resend.dev> or your domain):"
ask_secret RESEND_API_KEY "Paste Resend API key:"
write_env SMTP_HOST smtp.resend.com
write_env SMTP_PORT 587
write_env SMTP_SECURE true
write_env SMTP_USER resend
write_env SMTP_PASS "$RESEND_API_KEY"
write_env SMTP_FROM "$SMTP_FROM"
pause "SMTP saved. Press Enter."

# ── 4. Deploy API on Render ───────────────────────────────────────────────
stage "Render API"
say "Deploy the API with the Docker blueprint (render.yaml in the repo root)."
open_url "https://dashboard.render.com/select-repo?type=blueprint"
step "Sign in to Render → connect this GitHub/GitLab repo."
step "Choose Blueprint → apply render.yaml (service gamescore-api)."
step "When Render asks for env vars (sync:false), paste from $ENV_FILE:"
note "  DATABASE_URL, JWT_SECRET, JWT_REFRESH_SECRET,"
note "  SMTP_HOST, SMTP_PORT, SMTP_SECURE, SMTP_USER, SMTP_PASS, SMTP_FROM"
step "For now set CORS_ORIGINS=http://localhost:3000 (temporary) and"
step "NEXT_PUBLIC_SITE_URL=http://localhost:3000 — we fix after Vercel."
step "Wait until the deploy is Live, then open the service → copy the URL"
step "(https://gamescore-api-xxxx.onrender.com)."
ask NEXT_PUBLIC_API_URL "Paste the Render API URL (no trailing slash):"
# strip trailing slash
NEXT_PUBLIC_API_URL="${NEXT_PUBLIC_API_URL%/}"
write_env NEXT_PUBLIC_API_URL "$NEXT_PUBLIC_API_URL"
write_env API_INTERNAL_URL "$NEXT_PUBLIC_API_URL"
pause "API URL saved. Press Enter."

# ── 5. Deploy web on Vercel ───────────────────────────────────────────────
stage "Vercel web"
say "Import the same repo; vercel.json at the root configures the monorepo build."
open_url "https://vercel.com/new"
step "Import the GameScore repo (Root Directory = repository root, not apps/web)."
step "Framework: Next.js (auto). Keep install/build from vercel.json."
step "Environment Variables → add:"
note "  NEXT_PUBLIC_API_URL = $NEXT_PUBLIC_API_URL"
note "  NEXT_PUBLIC_SITE_URL = (leave blank for now or use a guess; we rebuild)"
note "  API_INTERNAL_URL = $NEXT_PUBLIC_API_URL"
step "Deploy. When done, copy the Production URL (https://….vercel.app)."
ask NEXT_PUBLIC_SITE_URL "Paste the Vercel site URL (no trailing slash):"
NEXT_PUBLIC_SITE_URL="${NEXT_PUBLIC_SITE_URL%/}"
write_env NEXT_PUBLIC_SITE_URL "$NEXT_PUBLIC_SITE_URL"
write_env CORS_ORIGINS "$NEXT_PUBLIC_SITE_URL"
pause "Vercel URL saved. Press Enter."

# ── 6. Wire CORS + email links on Render ──────────────────────────────────
stage "Update Render CORS + site URL"
say "The API must allow the exact Vercel origin and use it in email links."
open_url "https://dashboard.render.com/"
step "Open gamescore-api → Environment."
step "Set CORS_ORIGINS=$NEXT_PUBLIC_SITE_URL"
step "Set NEXT_PUBLIC_SITE_URL=$NEXT_PUBLIC_SITE_URL"
step "Save → Manual Deploy → Deploy latest commit (or wait for auto restart)."
pause "After Render finishes redeploying, press Enter."

# ── 7. Rebuild Vercel with final public URLs ──────────────────────────────
stage "Rebuild Vercel with final env"
say "NEXT_PUBLIC_* are baked at build time (CSP connect-src included)."
open_url "https://vercel.com/dashboard"
step "Project → Settings → Environment Variables."
step "Set NEXT_PUBLIC_API_URL=$NEXT_PUBLIC_API_URL"
step "Set NEXT_PUBLIC_SITE_URL=$NEXT_PUBLIC_SITE_URL"
step "Set API_INTERNAL_URL=$NEXT_PUBLIC_API_URL"
step "Deployments → … on latest → Redeploy (uncheck 'Use existing Build Cache')."
pause "After the redeploy succeeds, press Enter."

finish

printf '%sNext checks%s\n' "$BOLD" "$RESET"
note "1. Open $NEXT_PUBLIC_SITE_URL and register a user."
note "2. Confirm the verification email arrives (Resend dashboard → Logs)."
note "3. Confirm email, then post a review."
note "4. Full checklist: docs/deploy-beta.md"
note "Secrets live in $ENV_FILE — never commit that file."
printf '\n'
